"""Verificarea lock-ului fata de fisierele requirements (fara retea: regenerarea e simulata)."""

from __future__ import annotations

import importlib.util
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
_spec = importlib.util.spec_from_file_location("check_lock", ROOT / "tools" / "check_lock.py")
assert _spec and _spec.loader
check_lock = importlib.util.module_from_spec(_spec)
sys.modules["check_lock"] = check_lock
_spec.loader.exec_module(check_lock)

LOCK = """\
#
# This file is autogenerated by pip-compile with Python 3.12
# by the following command:
#
#    pip-compile --output-file=requirements.lock requirements-dev.txt
#
pytest==9.2.0 \\
    --hash=sha256:aaa
    # via -r requirements-dev.txt
"""


def test_header_is_ignored() -> None:
    other_header = LOCK.replace("--output-file=requirements.lock",
                                "--output-file=.lock-check-123.txt")
    assert check_lock.differences(LOCK, other_header) == []


def test_changed_pin_is_reported() -> None:
    changed = LOCK.replace("pytest==9.2.0", "pytest==9.1.0")
    diff = check_lock.differences(LOCK, changed)
    assert "-pytest==9.2.0 \\" in diff
    assert "+pytest==9.1.0 \\" in diff


def test_line_endings_do_not_matter() -> None:
    assert check_lock.differences(LOCK, LOCK.replace("\n", "\r\n")) == []


def test_main_passes_when_in_sync(tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
                                  capsys: pytest.CaptureFixture) -> None:
    (tmp_path / "requirements.lock").write_text(LOCK, encoding="utf-8")
    monkeypatch.setattr(check_lock, "regenerate", lambda root: LOCK)
    assert check_lock.main(["--root", str(tmp_path)]) == 0
    assert "e sincronizat" in capsys.readouterr().out


def test_main_fails_with_diff_and_fix_command(tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
                                              capsys: pytest.CaptureFixture) -> None:
    (tmp_path / "requirements.lock").write_text(LOCK, encoding="utf-8")
    monkeypatch.setattr(check_lock, "regenerate",
                        lambda root: LOCK.replace("9.2.0", "9.1.0"))
    monkeypatch.setenv("GITHUB_ACTIONS", "true")
    assert check_lock.main(["--root", str(tmp_path)]) == 1
    out, err = capsys.readouterr()
    assert "+pytest==9.1.0 \\" in out
    assert "::error file=requirements.lock::" in out
    assert check_lock.FIX_COMMAND in err
    assert "--upgrade" not in check_lock.FIX_COMMAND  # versiunile existente raman
